                  ? folio.updatedAt
                  : undefined,
              layout: folio.layout,
              header:
                typeof folio.header === "string" ? folio.header : undefined,
              footer:
                typeof folio.footer === "string" ? folio.footer : undefined,
            },
            html: typeof body.html === "string" ? body.html : undefined,
            brief: body.brief,
            expectedUpdatedAt:
              typeof body.expectedUpdatedAt === "number"
                ? body.expectedUpdatedAt
                : undefined,
          });
          break;
        }
        case "feedback.get":
          data = await ctx.runQuery(internal.integrations.getFeedback, {
            userId: auth.userId,
            folioId: integrationString(body.folioId, "folioId"),
          });
          break;
        case "citations.list":
          data = await ctx.runQuery(internal.integrations.listCitations, {
            userId: auth.userId,
            folioId:
              typeof body.folioId === "string" ? body.folioId : undefined,
            search: typeof body.search === "string" ? body.search : undefined,
          });
          break;
        case "citations.put":
          if (!Array.isArray(body.entries)) {
            throw new Error("entries must be an array");
          }
          data = await ctx.runMutation(internal.integrations.putCitations, {
            userId: auth.userId,
            folioId: integrationString(body.folioId, "folioId"),
            entries: body.entries,
          });
          break;
        case "folios.search":
          data = await ctx.runQuery(internal.integrations.searchFolios, {
            userId: auth.userId,
            search: integrationString(body.search, "search"),
            limit:
              typeof body.limit === "number" && Number.isFinite(body.limit)
                ? body.limit
                : 20,
          });
          break;
        default:
          return integrationError("Unknown operation", 400);
      }
      return integrationJson({ ok: true, data });
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Integration request failed";
      const status = message.includes("changed since it was read") ? 409 : 400;
      return integrationError(message, status);
    }
  }),
});

/* ── Creem payment webhook ──────────────────────────────────────────
 * Creem POSTs subscription lifecycle events here. We verify the
 * `creem-signature` header (HMAC-SHA256 over the raw body with
 * CREEM_WEBHOOK_SECRET) before recording entitlement. Unverified or
 * malformed requests are rejected without touching the database.
 *
 * After verification, the event is parsed through an accepted-type
 * allowlist (`parseCreemEvent`) and applied idempotently
 * (`applyCreemEvent`): duplicate event ids and out-of-order/stale events
 * are ignored, and only Pro-allowlisted products can ever grant Pro. */

async function hmacHex(secret: string, body: string): Promise<string> {
  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const sig = await crypto.subtle.sign(
    "HMAC",
    key,
    new TextEncoder().encode(body),
  );
  return Array.from(new Uint8Array(sig))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

/** Constant-time compare on equal-length hex strings. */
function safeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

http.route({
  path: "/creem/webhook",
  method: "POST",
  handler: httpAction(async (ctx, request) => {
    const secret = process.env.CREEM_WEBHOOK_SECRET;
    if (!secret) return new Response("not configured", { status: 503 });

    const raw = await request.text();
    const provided = request.headers.get("creem-signature") ?? "";
    const expected = await hmacHex(secret, raw);
    if (!provided || !safeEqual(provided.toLowerCase(), expected)) {
      return new Response("invalid signature", { status: 401 });
    }

    let event: any;
    try {
      event = JSON.parse(raw);
    } catch {
      return new Response("bad json", { status: 400 });
    }

    const parsed = parseCreemEvent(event);
    if (!parsed) return new Response("ignored", { status: 202 });

    try {
      await ctx.runMutation(internal.payments.applyCreemEvent, {
        ...parsed.update,
        eventId: parsed.eventId ?? undefined,
        eventCreatedAt: parsed.eventCreatedAt ?? undefined,
        eventType: parsed.eventType,
      });
      return new Response("ok", { status: 200 });
    } catch (err) {
      // A failed webhook is the worst silent failure: a real subscriber
      // could lose Pro without anyone noticing. Report it and surface a
      // 500 so Creem retries (and we have a chance to fix forward).
      reportError({
        feature: "creem.webhook",
        error: err,
        context: {
          eventType: parsed.eventType,
          eventId: parsed.eventId ?? undefined,
          userId: parsed.update.userId,
        },
      });
      return new Response("internal error", { status: 500 });
    }
  }),
});

